//! Named colour themes modelled on VS Code's built-in ones (palettes from the MIT-licensed
//! microsoft/vscode `extensions/theme-*` and the default terminal colours, mapped onto wi's own
//! roles; no code copied). Each theme is one `Spec` row of base colours; `build` derives every
//! `Theme` role from it. Rows were generated by a small script that moved a colour toward white
//! or black only where it missed its contrast target (4.5:1 for text, 7:1 in the high-contrast
//! themes, 3:1 for lines and borders), so hues stay recognisable. `Spec::ansi` starts from the
//! theme's `terminal.ansi*` colours (VS Code's defaults where the theme sets none).

use super::{Kind, Theme, c};

pub struct Spec {
    pub name: &'static str,
    pub label: &'static str,
    pub kind: Kind,
    pub bg: u32,
    pub fg: u32,
    pub dim: u32,
    pub bar_bg: u32,
    pub bar_fg: u32,
    pub status_bg: u32,
    pub status_fg: u32,
    /// Menu and dialog background.
    pub panel: u32,
    pub accent: u32,
    pub on_accent: u32,
    pub sel_bg: u32,
    pub sel_fg: u32,
    /// Link-label colour (text on it is `hint_fg`).
    pub hint: u32,
    pub hint_fg: u32,
    /// Quiet lines: dividers, rules, guides.
    pub rule: u32,
    pub code_bg: u32,
    pub goto_bg: u32,
    pub col_head: u32,
    pub purple: u32,
    pub cyan: u32,
    pub blue: u32,
    pub red: u32,
    pub green: u32,
    pub yellow: u32,
    pub ansi: [u32; 16],
}

/// Every role of a theme from its base colours.
pub const fn build(s: &Spec) -> Theme {
    Theme {
        name: s.name,
        label: s.label,
        kind: s.kind,
        bg: c(s.bg),
        fg: c(s.fg),
        dim: c(s.dim),
        bar_bg: c(s.bar_bg),
        bar_fg: c(s.bar_fg),
        header: c(s.bar_fg),
        status_bg: c(s.status_bg),
        status_fg: c(s.status_fg),
        tab_active_bg: c(s.accent),
        tab_active_fg: c(s.on_accent),
        tab_inactive: c(s.bar_fg),
        tab_streaming: c(s.yellow),
        tab_quiet: c(s.green),
        menu_bg: c(s.panel),
        menu_fg: c(s.fg),
        menu_border: c(s.accent),
        menu_sel_bg: c(s.accent),
        menu_sel_fg: c(s.on_accent),
        menu_hotkey: c(s.yellow),
        dialog_bg: c(s.panel),
        dialog_fg: c(s.fg),
        dialog_border: c(s.accent),
        dialog_dim: c(s.dim),
        divider_focus: c(s.accent),
        divider_idle: c(s.rule),
        hint_bg: c(s.hint),
        hint_fg: c(s.hint_fg),
        sel_bg: c(s.sel_bg),
        sel_fg: c(s.sel_fg),
        goto_bg: c(s.goto_bg),
        gutter: c(s.dim),
        banner: c(s.yellow),
        md_h1: c(s.purple),
        md_h2: c(s.cyan),
        md_h3: c(s.blue),
        md_code: c(s.dim),
        md_quote: c(s.dim),
        md_link: c(s.blue),
        md_bullet: c(s.yellow),
        md_rule: c(s.rule),
        md_code_bg: c(s.code_bg),
        md_quote_bar: c(s.rule),
        md_task_done: c(s.green),
        md_task_open: c(s.fg),
        md_front: c(s.dim),
        json_key: c(s.cyan),
        json_string: c(s.green),
        json_number: c(s.yellow),
        table_header: c(s.fg),
        table_sep: c(s.rule),
        diff_add: c(s.green),
        diff_remove: c(s.red),
        diff_hunk: c(s.cyan),
        diff_file: c(s.fg),
        diff_untracked: c(s.yellow),
        diff_branch: c(s.fg),
        error: c(s.red),
        warning: c(s.yellow),
        title_bg: c(s.fg),
        title_fg: c(s.bg),
        hintline_fg: c(s.dim),
        badge_bg: c(s.accent),
        badge_fg: c(s.on_accent),
        col_header_bg: c(s.col_head),
        col_header_fg: c(s.fg),
        tree_guide: c(s.rule),
        size_fg: c(s.dim),
        date_fg: c(s.dim),
        row_sel_bg: c(s.sel_bg),
        row_sel_fg: c(s.sel_fg),
        good: c(s.green),
        warn: c(s.yellow),
        hot: c(s.red),
        ansi: {
            let mut a = [c(0); 16];
            let mut i = 0;
            while i < 16 {
                a[i] = c(s.ansi[i]);
                i += 1;
            }
            a
        },
    }
}

